int maxProfit(const vector<int>& p) {
    int best = 0, minSoFar = INT_MAX;
    for (int x : p) {
        best = max(best, x - minSoFar);   // sell today against cheapest past day
        minSoFar = min(minSoFar, x);      // update AFTER: cannot buy and sell same day
    }
    return best;
}

