int majorityElement(const vector<int>& a) {
    int cand = a[0], count = 0;
    for (int x : a) {
        if (count == 0) cand = x;              // no standing candidate
        count += (x == cand) ? 1 : -1;         // distinct values cancel
    }
    // verify: guard for callers where a majority may not exist
    int seen = 0;
    for (int x : a) if (x == cand) ++seen;
    return seen > (int)a.size() / 2 ? cand : -1;
}

