    cand, count = a[0], 0
    for x in a:
        if count == 0:
            cand = x                 # no standing candidate
        count += 1 if x == cand else -1   # distinct values cancel
    # verify: guard for callers where a majority may not exist
    return cand if a.count(cand) > len(a) // 2 else -1

