vector<int> productExceptSelf(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, 1);
    for (int i = 1; i < n; ++i)
        out[i] = out[i - 1] * a[i - 1];   // out[i] = product of everything left of i
    int right = 1;
    for (int i = n - 1; i >= 0; --i) {
        out[i] *= right;                  // fold in everything right of i
        right *= a[i];
    }
    return out;
}

