int pivotIndex(const vector<int>& a) {
    int total = 0;
    for (int x : a) total += x;
    int left = 0;
    for (int i = 0; i < (int)a.size(); ++i) {
        if (left == total - left - a[i]) return i;   // right side = total - left - a[i]
        left += a[i];
    }
    return -1;
}

int maxArea(const vector<int>& h) {
    int l = 0, r = (int)h.size() - 1, best = 0;
    while (l < r) {
        best = max(best, (r - l) * min(h[l], h[r]));
        if (h[l] < h[r]) ++l; else --r;   // moving the taller wall can never help
    }
    return best;
}

