vector<int> twoSum(const vector<int>& a, int target) {
    int l = 0, r = (int)a.size() - 1;
    while (l < r) {
        int sum = a[l] + a[r];
        if (sum == target) return {l + 1, r + 1};   // problem wants 1-based
        if (sum < target) ++l;                      // need a bigger sum
        else --r;                                   // need a smaller sum
    }
    return {};
}

