double findMaxAverage(const vector<int>& a, int k) {
    long long sum = 0;
    for (int i = 0; i < k; ++i) sum += a[i];
    long long best = sum;
    for (size_t i = k; i < a.size(); ++i) {
        sum += a[i] - a[i - k];    // one in, one out
        best = max(best, sum);
    }
    return (double)best / k;
}

int minSubArrayLen(int target, const vector<int>& a) {
    int l = 0, best = INT_MAX;
    long long sum = 0;
    for (int r = 0; r < (int)a.size(); ++r) {
        sum += a[r];
        while (sum >= target) {              // shrink while still satisfying
            best = min(best, r - l + 1);
            sum -= a[l++];
        }
    }
    return best == INT_MAX ? 0 : best;
}

int maxSubarraySumCircular(const vector<int>& a) {
    int total = 0;
    int curMax = 0, best = INT_MIN;
    int curMin = 0, worst = INT_MAX;
    for (int x : a) {
        total += x;
        curMax = max(x, curMax + x);  best = max(best, curMax);
        curMin = min(x, curMin + x);  worst = min(worst, curMin);
    }
    // all-negative: the wrapped candidate would be the empty subarray
    return best > 0 ? max(best, total - worst) : best;
}
